head.script:
// /*DQ-AD-GATE*/
  (function(){
    var CLIENT='ca-pub-1235197294708204',MIN=350,tries=0,done=false;
    function eligible(){
      var m=document.querySelector('meta[name="dq-pagetype"]'),pt=m?m.getAttribute('content'):'';
      if(pt!=='item'&&pt!=='static_page')return false;
      var main=document.querySelector('#main-content');if(!main||main.querySelector('.hub'))return false;
      var c=main.querySelector('.prose');if(!c)return false;c=c.cloneNode(true);
      c.querySelectorAll('.tool,.related,script,style,nav').forEach(function(n){n.remove();});
      return (c.textContent||'').split(/\s+/).filter(function(w){return w.length>1;}).length>=MIN;
    }
    function load(){if(done)return;done=true;var s=document.createElement('script');s.async=true;s.crossOrigin='anonymous';s.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+CLIENT;document.head.appendChild(s);}
    function check(){if(done)return;tries++;try{if(eligible()){load();return;}}catch(e){}if(tries<8)setTimeout(check,900);}
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(check,500);});else setTimeout(check,500);
  })();
  //

head.b:skin:
/* دقّة — تصميم هادئ بطابع تحريري: ورق دافئ، حبر كحلي، لمسة طوب. بلا تدرجات ولا توهّج ولا أيقونات جاهزة. */
:root{--paper:#f6f2ea;--card:#fffdf8;--ink:#1d2733;--soft:#4a5663;--faint:#7a828b;--rule:#d9d2c3;--rule2:#b9b09b;--brick:#9b3a1e;--steel:#28506f;--mark:#efe4c8;--ok:#2f6b4f;
--ui:'Noto Kufi Arabic','Segoe UI',Tahoma,sans-serif;--read:'Noto Naskh Arabic','Traditional Arabic',Georgia,serif}
html[data-theme=dark]{--paper:#14181d;--card:#1b2128;--ink:#ece7dc;--soft:#b9b4a8;--faint:#8b9097;--rule:#2d353e;--rule2:#47515c;--brick:#e08a68;--steel:#8fb5d3;--mark:#2a2f2a;--ok:#7fc4a0}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.9 var(--read);font-variant-numeric:lining-nums}
a{color:var(--steel);text-underline-offset:3px}a:hover{color:var(--brick)}
h1,h2,h3,h4,.ui{font-family:var(--ui);color:var(--ink);line-height:1.5;font-weight:700}
.wrap{width:min(1080px,100% - 32px);margin-inline:auto}
.skip{position:absolute;top:-60px;inset-inline-start:8px;background:var(--ink);color:var(--paper);padding:8px 14px;z-index:99}.skip:focus{top:8px}
/* ترويسة */
.top{border-bottom:2px solid var(--ink);background:var(--paper);position:sticky;top:0;z-index:20}
.bar{display:flex;align-items:center;gap:20px;min-height:64px}
.brand{font:700 28px/1 var(--ui);color:var(--ink);text-decoration:none;letter-spacing:0;display:flex;align-items:baseline;gap:10px}
.brand small{font:500 13px/1.3 var(--ui);color:var(--faint)}
.nav{display:flex;gap:4px;margin-inline-start:auto;align-items:center}
.nav a{font:500 15px var(--ui);color:var(--ink);text-decoration:none;padding:8px 12px;border-bottom:2px solid transparent}
.nav a:hover,.nav a[aria-current]{border-bottom-color:var(--brick);color:var(--ink)}
.iconbtn{font:500 14px var(--ui);background:none;border:1px solid var(--rule2);color:var(--ink);padding:6px 12px;cursor:pointer;border-radius:3px}
.iconbtn:hover{border-color:var(--ink)}
.burger{display:none}
#nav-t{display:none}
/* شريط اليوم */
.today{background:var(--ink);color:var(--paper);font:500 14px/1.4 var(--ui)}
.today .wrap{display:flex;gap:18px;flex-wrap:wrap;padding:9px 0;align-items:center}
.today b{font-weight:700}.today span{opacity:.85}
/* الصفحة الرئيسية */
.intro{padding:52px 0 36px;border-bottom:1px solid var(--rule)}
.intro h1{font-size:clamp(28px,5vw,46px);margin:0 0 14px;max-width:22ch;font-weight:700}
.intro p{font-size:20px;color:var(--soft);max-width:60ch;margin:0}
.intro .wrap{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:56px;align-items:center}
.plate{border:1px solid var(--rule2);background:var(--card);min-height:248px}
.plate>div{padding:20px 24px;display:grid;grid-template-columns:auto 1fr;gap:4px 20px;align-items:center}
.plate>div+div{border-top:1px solid var(--rule2)}
.plate small{grid-column:1/-1;font:600 13px var(--ui);color:var(--faint)}
.plate .d{font:700 64px/1 var(--ui);color:var(--brick);font-variant-numeric:tabular-nums}
.plate .m{font:600 20px/1.5 var(--ui);color:var(--ink)}.plate .m span{display:block;font:500 15px var(--ui);color:var(--soft)}
.quick{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}
.sec{padding:40px 0 8px}.sec>h2{font-size:22px;margin:0 0 4px;display:flex;align-items:baseline;gap:14px}.sec>h2 small{font:500 14px var(--ui);color:var(--faint)}
.sec>p.lead{color:var(--soft);margin:0 0 14px}
.idx{list-style:none;margin:10px 0 0;padding:0;border-top:2px solid var(--ink)}
.idx li{border-bottom:1px solid var(--rule)}
.idx a{display:grid;grid-template-columns:44px 1fr auto;gap:14px;align-items:baseline;padding:16px 4px;text-decoration:none;color:var(--ink)}
.idx a:hover{background:var(--mark)}
.idx .n{font:700 15px var(--ui);color:var(--brick);font-variant-numeric:tabular-nums}
.idx .t{font:700 18px/1.5 var(--ui)}.idx .d{display:block;font:400 16px/1.7 var(--read);color:var(--soft);margin-top:2px}
.idx .go{font:500 14px var(--ui);color:var(--faint)}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:0 56px}.cols .sec{padding-top:36px}
.group{font:700 14px var(--ui);color:var(--steel);margin:30px 0 -4px;padding-bottom:6px}
.posts{list-style:none;margin:10px 0 0;padding:0;border-top:2px solid var(--ink)}
.posts li{border-bottom:1px solid var(--rule);padding:18px 4px}
.posts a{font:700 19px/1.6 var(--ui);color:var(--ink);text-decoration:none}.posts a:hover{color:var(--brick)}
.posts p{margin:4px 0 0;color:var(--soft);font-size:17px;line-height:1.8}
.meta{font:500 13px var(--ui);color:var(--faint);display:flex;gap:14px;flex-wrap:wrap}
.method{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:14px;border-top:2px solid var(--ink)}
.method div{padding:20px 20px 20px 0;border-inline-start:1px solid var(--rule);padding-inline-start:20px}.method div:first-child{border-inline-start:0;padding-inline-start:0}
.method h3{font-size:17px;margin:0 0 6px}.method p{margin:0;color:var(--soft);font-size:17px;line-height:1.8}
/* صفحات المحتوى */
.page{padding:30px 0 24px}
.crumbs{font:500 13px var(--ui);color:var(--faint);margin-bottom:12px}.crumbs a{color:var(--faint)}
.page h1{font-size:clamp(26px,4.4vw,38px);margin:0 0 10px;font-weight:700}
.lede{font-size:20px;color:var(--soft);margin:0 0 20px;max-width:62ch}
.layout{display:grid;grid-template-columns:minmax(0,720px) 250px;gap:64px;justify-content:start}
.side{padding-top:6px;font:500 15px/1.7 var(--ui)}.side h4{font-size:14px;color:var(--faint);margin:0 0 8px;border-bottom:1px solid var(--rule);padding-bottom:6px}
.side ul{list-style:none;padding:0;margin:0 0 26px}.side li{padding:5px 0}.side a{text-decoration:none;color:var(--ink)}.side a:hover{color:var(--brick)}
#toc{margin:0 0 26px;padding:14px 18px;border:1px solid var(--rule);background:var(--card);font:500 15px/1.8 var(--ui)}#toc ol{margin:6px 0 0;padding-inline-start:22px}#toc[hidden]{display:none}
.prose{max-width:none}.prose>p,.prose>ul,.prose>ol,.prose>blockquote{max-width:68ch}.prose h2{font-size:24px;margin:2em 0 .5em;padding-top:.3em;border-top:1px solid var(--rule)}.prose h3{font-size:19px;margin:1.6em 0 .3em}
.prose p,.prose li{margin:.8em 0}.prose ul,.prose ol{padding-inline-start:1.5em}
.prose table{border-collapse:collapse;width:100%;margin:1.2em 0;font:400 16px/1.6 var(--ui);display:table}
.prose th,.prose td{border:1px solid var(--rule2);padding:9px 12px;text-align:start}.prose th{background:var(--mark);font-weight:700}
.prose blockquote{margin:1.4em 0;padding:4px 18px;border-inline-start:4px solid var(--brick);background:var(--card);color:var(--soft)}
.prose code{font:15px ui-monospace,monospace;background:var(--mark);padding:1px 6px;direction:ltr;unicode-bidi:embed}
.prose .eq{display:block;direction:ltr;text-align:center;font:17px ui-monospace,monospace;background:var(--card);border:1px solid var(--rule);padding:12px;margin:1.2em 0;overflow-x:auto}
.byline{font:500 14px var(--ui);color:var(--faint);display:flex;gap:16px;flex-wrap:wrap;padding:10px 0 18px;border-bottom:1px solid var(--rule);margin-bottom:20px}
.related{margin-top:34px;border-top:2px solid var(--ink);padding-top:6px}.related h2{font-size:18px;margin:10px 0}
.pager{display:flex;justify-content:space-between;gap:16px;margin:34px 0 0;font:500 15px var(--ui)}
.labels{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px}.labels a{font:500 13px var(--ui);border:1px solid var(--rule2);padding:2px 10px;text-decoration:none;color:var(--soft)}
/* الأدوات */
.tool{background:var(--card);border:1px solid var(--rule2);border-top:4px solid var(--brick);padding:22px;margin:8px 0 30px}
.tool h3{margin:0 0 10px;font-size:17px}.tool h3:not(:first-child){margin-top:26px;padding-top:18px;border-top:1px dashed var(--rule2)}
.grid2,.grid3{display:grid;gap:14px 18px}.grid2{grid-template-columns:1fr 1fr}.grid3{grid-template-columns:1fr 1fr 1fr}
.fld{display:flex;flex-direction:column;gap:5px;margin:0 0 14px}.fld label,.chk{font:600 14px var(--ui);color:var(--soft)}.fld small{color:var(--faint);font:400 13px var(--ui)}
.tool input,.tool select,.tool textarea{font:500 17px var(--ui);background:var(--paper);color:var(--ink);border:1px solid var(--rule2);border-radius:3px;padding:10px 12px;width:100%;min-height:46px}
.tool input[type=checkbox]{width:18px;min-height:0;vertical-align:middle}
.tool textarea{font-family:var(--read);line-height:1.8;resize:vertical}
.tool input:focus,.tool select:focus,.tool textarea:focus,.btn:focus-visible,.iconbtn:focus-visible,a:focus-visible{outline:3px solid var(--steel);outline-offset:1px}
.out{margin-top:10px;border-top:1px solid var(--rule);padding-top:12px}
.big{font:700 clamp(22px,4.6vw,32px)/1.5 var(--ui);color:var(--brick);margin:4px 0 10px}.big.words{font:700 clamp(20px,3.6vw,26px)/1.9 var(--read)}
.r{display:flex;justify-content:space-between;gap:16px;padding:8px 0;border-bottom:1px solid var(--rule);font:400 16px/1.6 var(--ui)}.r .k{color:var(--soft)}.r .v{font-weight:600;text-align:end}
.note{font:400 14px/1.8 var(--ui);color:var(--soft);background:var(--mark);padding:10px 14px;margin:12px 0 0}
.sub{font:500 14px var(--ui);color:var(--faint);margin:10px 0 4px}
.btn{font:600 15px var(--ui);background:var(--ink);color:var(--paper);border:0;padding:11px 20px;cursor:pointer;border-radius:3px;text-decoration:none;display:inline-block}.btn:hover{background:var(--brick);color:#fff}
.btn.alt{background:none;color:var(--ink);border:1px solid var(--ink)}.btn.alt:hover{background:var(--ink);color:var(--paper)}
table.mini{width:100%;border-collapse:collapse;font:400 15px var(--ui)}table.mini td{border-bottom:1px solid var(--rule);padding:6px 4px}table.mini td+td{text-align:end;font-variant-numeric:tabular-nums}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:10px}.stats div{border:1px solid var(--rule);padding:10px;text-align:center;font-family:var(--ui)}.stats b{display:block;font-size:22px;color:var(--brick)}.stats span{font-size:13px;color:var(--soft)}
.tags span{display:inline-block;border:1px solid var(--rule2);padding:2px 10px;margin:0 0 6px 6px;font:500 14px var(--ui)}
.faq details{border-bottom:1px solid var(--rule);padding:12px 0}.faq summary{font:700 17px var(--ui);cursor:pointer}.faq p{margin:8px 0 0}
/* تذييل */
.foot{margin-top:60px;border-top:2px solid var(--ink);padding:36px 0 0;font:400 15px/1.9 var(--ui)}
.fg{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:32px}.foot h4{font-size:14px;margin:0 0 10px;color:var(--faint)}.foot ul{list-style:none;margin:0;padding:0}.foot li{padding:3px 0}.foot a{color:var(--ink);text-decoration:none}.foot a:hover{color:var(--brick);text-decoration:underline}
.foot .b{font:700 24px var(--ui);margin-bottom:8px}.foot p{margin:0;color:var(--soft);max-width:34ch}
.fb{border-top:1px solid var(--rule);margin-top:30px;padding:16px 0 26px;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;color:var(--faint);font-size:14px}
.err{padding:90px 0;text-align:center}.err h1{font-size:60px;margin:0;color:var(--brick)}
[hidden]{display:none!important}
@media(max-width:860px){.intro .wrap{grid-template-columns:1fr;gap:28px}.plate{min-height:0}.layout{grid-template-columns:1fr}.side{order:2}.cols,.method{grid-template-columns:1fr}.method div{border-inline-start:0;padding-inline-start:0;border-top:1px solid var(--rule)}.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:1/-1}}
@media(max-width:700px){body{font-size:17px}.burger{display:inline-block}.nav{position:absolute;inset-inline:0;top:100%;background:var(--paper);border-bottom:2px solid var(--ink);flex-direction:column;align-items:stretch;padding:8px 16px;display:none}#nav-t:checked~.top .nav{display:flex}.nav a{padding:12px 4px;border-bottom:1px solid var(--rule)}.brand small{display:none}.intro{padding:34px 0 26px}.grid2,.grid3{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.tool{padding:16px}.idx a{grid-template-columns:34px 1fr}.idx .go{display:none}.bar{gap:10px}.nav-wrap{margin-inline-start:auto;display:flex;gap:8px}}
@media print{.top,.today,.foot,.side,.tool .btn{display:none}body{background:#fff;font-size:12pt}}

body.script:
//
/* دقّة — منطق الحساب (بلا واجهة). يعمل في المتصفح وفي Node للاختبار. */
var DaqqaCore = (function () {
  'use strict';
  var MS = 86400000;

  /* ---------- التواريخ ---------- */
  function utc(y, m, d) { var t = new Date(0); t.setUTCFullYear(y, m - 1, d); t.setUTCHours(12, 0, 0, 0); return t; } // ظهراً لتفادي مشاكل التوقيت
  function parseISO(s) { var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ''); if (!m) return null; var d = utc(+m[1], +m[2], +m[3]); return d.getUTCMonth() === +m[2] - 1 ? d : null; }
  function iso(d) { return d.getUTCFullYear().toString().padStart(4, '0') + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0'); }
  function diffDays(a, b) { return Math.round((b - a) / MS); }
  function addDays(d, n) { return new Date(d.getTime() + n * MS); }
  function isLeap(y) { return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; }
  function monthLen(y, m) { return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]; }

  /* فرق بالسنين والأشهر والأيام (ميلادي) */
  function addMonths(d, n) { var t = d.getUTCFullYear() * 12 + d.getUTCMonth() + n, y = Math.floor(t / 12), m = t % 12; return utc(y, m + 1, Math.min(d.getUTCDate(), monthLen(y, m + 1))); }
  function ymd(a, b) { // أكبر عدد أشهر كاملة (مع قصّ نهاية الشهر) ثم الأيام المتبقية
    var total = (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + b.getUTCMonth() - a.getUTCMonth();
    while (total > 0 && addMonths(a, total) > b) total--;
    return { y: Math.floor(total / 12), m: total % 12, d: diffDays(addMonths(a, total), b) };
  }

  /* ---------- الهجري (أم القرى عبر Intl) ---------- */
  var HF = null;
  function hfmt() { if (!HF) HF = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn', { year: 'numeric', month: 'numeric', day: 'numeric', timeZone: 'UTC' }); return HF; }
  function toHijri(d) {
    var o = {}; hfmt().formatToParts(d).forEach(function (p) { if (p.type !== 'literal' && p.type !== 'era') o[p.type] = parseInt(p.value, 10); });
    return { y: o.year, m: o.month, d: o.day };
  }
  function hcmp(a, b) { return a.y !== b.y ? a.y - b.y : a.m !== b.m ? a.m - b.m : a.d - b.d; }
  function fromHijri(y, m, d) {
    var g = new Date(Date.UTC(622, 6, 16, 12) + ((y - 1) * 354.367 + (m - 1) * 29.5306 + (d - 1)) * MS);
    for (var i = 0; i < 80; i++) {
      var h = toHijri(g), c = hcmp(h, { y: y, m: m, d: d });
      if (c === 0) return g;
      g = addDays(g, c > 0 ? -1 : 1);
      if (i > 60) { /* تاريخ غير موجود (مثلاً يوم 30 في شهر من 29) */ }
    }
    return null;
  }
  function hijriMonthLen(y, m) { var a = fromHijri(y, m, 1), ny = m === 12 ? y + 1 : y, nm = m === 12 ? 1 : m + 1, b = fromHijri(ny, nm, 1); return diffDays(a, b); }
  function validHijri(y, m, d) { if (m < 1 || m > 12 || d < 1) return false; var g = fromHijri(y, m, d); if (!g) return false; var h = toHijri(g); return h.y === y && h.m === m && h.d === d; }
  function ymdHijri(a, b) { // a, b: تواريخ ميلادية؛ الفرق بحساب الهجري
    var ha = toHijri(a), hb = toHijri(b), y = hb.y - ha.y, m = hb.m - ha.m, d = hb.d - ha.d;
    if (d < 0) { m--; var pm = hb.m === 1 ? 12 : hb.m - 1, py = hb.m === 1 ? hb.y - 1 : hb.y; d += hijriMonthLen(py, pm); }
    if (m < 0) { y--; m += 12; }
    return { y: y, m: m, d: d };
  }
  var HM = ['محرم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'جمادى الأولى', 'جمادى الآخرة', 'رجب', 'شعبان', 'رمضان', 'شوال', 'ذو القعدة', 'ذو الحجة'];
  var GM = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  var DN = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];

  /* أقرب تاريخ هجري قادم (شهر/يوم) بدءاً من تاريخ معيّن */
  function nextHijriOccurrence(from, hm, hd) {
    var h = toHijri(from), y = h.y;
    var g = fromHijri(y, hm, hd);
    if (!g || g < from) g = fromHijri(y + 1, hm, hd);
    return g;
  }

  /* ---------- أيام العمل ---------- */
  function businessDays(a, b, weekend, holidays) { // يشمل a ويستبعد b (عدد الأيام التي تمرّ)، weekend مصفوفة أرقام JS (0=أحد)
    var n = 0, hs = {}; (holidays || []).forEach(function (h) { hs[h] = 1; });
    var s = a <= b ? a : b, e = a <= b ? b : a;
    for (var d = s; d < e; d = addDays(d, 1)) { if (weekend.indexOf(d.getUTCDay()) < 0 && !hs[iso(d)]) n++; }
    return a <= b ? n : -n;
  }
  function addBusinessDays(a, n, weekend, holidays) {
    var hs = {}; (holidays || []).forEach(function (h) { hs[h] = 1; });
    var d = a, step = n >= 0 ? 1 : -1, left = Math.abs(n);
    while (left > 0) { d = addDays(d, step); if (weekend.indexOf(d.getUTCDay()) < 0 && !hs[iso(d)]) left--; }
    return d;
  }

  /* ---------- الأرقام بالحروف ---------- */
  var M1 = ['', 'واحد', 'اثنان', 'ثلاثة', 'أربعة', 'خمسة', 'ستة', 'سبعة', 'ثمانية', 'تسعة', 'عشرة'];
  var F1 = ['', 'واحدة', 'اثنتان', 'ثلاث', 'أربع', 'خمس', 'ست', 'سبع', 'ثمان', 'تسع', 'عشر'];
  var TEEN_M = ['عشرة', 'أحد عشر', 'اثنا عشر', 'ثلاثة عشر', 'أربعة عشر', 'خمسة عشر', 'ستة عشر', 'سبعة عشر', 'ثمانية عشر', 'تسعة عشر'];
  var TEEN_F = ['عشر', 'إحدى عشرة', 'اثنتا عشرة', 'ثلاث عشرة', 'أربع عشرة', 'خمس عشرة', 'ست عشرة', 'سبع عشرة', 'ثماني عشرة', 'تسع عشرة'];
  var TENS = ['', '', 'عشرون', 'ثلاثون', 'أربعون', 'خمسون', 'ستون', 'سبعون', 'ثمانون', 'تسعون'];
